// ─── Build Escalation Payload (FR-9) ─────────────────────────────────────────
// Constructs the full WhatsApp escalation message for the admin.
// Assigns a short escalation_id used for all subsequent admin replies.
// ─────────────────────────────────────────────────────────────────────────────

const upstream = $input.first().json;

// ── 1. Generate escalation ID ─────────────────────────────────────────────────
const escalation_id = 'ESC-' + Date.now().toString(36).toUpperCase().slice(-6);

// ── 2. Determine escalation reason ────────────────────────────────────────────
let escalation_reason = 'low_confidence';
if (!upstream.solutionMd || upstream.solutionMd.trim().length < 50) {
  escalation_reason = 'empty_or_short_solution';
} else if (upstream.subject === 'Unknown' || upstream.topic === 'Unknown') {
  escalation_reason = 'unclassified_topic';
} else if ((upstream.confidence ?? 1) < 0.75) {
  escalation_reason = 'low_confidence';
}

// ── 3. Build Telegram thread deep-link ────────────────────────────────────────
// Group chats have negative IDs like -100XXXXXXXXX; strip the -100 prefix
const rawChatId = String(upstream.chatId || '');
const cleanChatId = rawChatId.startsWith('-100') ? rawChatId.slice(4) : rawChatId.replace('-', '');
const threadLink = `https://t.me/c/${cleanChatId}/${upstream.threadMessageId}`;

// ── 4. Truncate AI draft for WhatsApp (4096 char limit) ───────────────────────
const draft = upstream.solutionMd || '';
const draftPreview = draft;

// Strip HTML tags for WhatsApp readability
const draftClean = draftPreview
  .replace(/<b>/gi, '*').replace(/<\/b>/gi, '*')
  .replace(/<i>/gi, '_').replace(/<\/i>/gi, '_')
  .replace(/<code>/gi, '`').replace(/<\/code>/gi, '`')
  .replace(/<pre>/gi, '```\n').replace(/<\/pre>/gi, '\n```')
  .replace(/<[^>]+>/g, '');

// ── 5. Build multi-line WhatsApp message ──────────────────────────────────────
const waMessageText = [
  `🚨 <b>ESCALATION [${escalation_id}]</b>`,
  ``,
  `👤 <b>Student:</b> ${upstream.fromUsername || 'Unknown'}`,
  `📚 <b>Subject:</b> ${upstream.subject || 'Unknown'} → ${upstream.chapter || 'Unknown'}`,
  `🔖 <b>Topic:</b> ${upstream.topic || 'Unknown'}`,
  `📊 <b>Difficulty:</b> ${upstream.difficulty || 'medium'}`,
  `🎯 <b>AI Confidence:</b> ${upstream.confidence ?? 0}%`,
  `⚠️ <b>Reason:</b> ${escalation_reason}`,
  ``,
  `❓ <b>Question:</b>`,
  upstream.questionText?.trim() || '<i>(image only — no caption text)</i>',
  ``,
  `🤖 <b>AI Draft (preview):</b>`,
  draftClean,
  ``,
  `🔗 <b>Telegram Thread:</b> ${threadLink}`,
  ``,
  `──────────────────────────`,
  `Reply options:`,
  `• Type your solution (include <code>[${escalation_id}]</code>)`,
  `• Send a voice note with <code>[${escalation_id}]</code> in caption`,
  `• <b>PENDING</b> — see all open escalations`,
  `• <b>UPDATE ${escalation_id}</b> — save final to knowledge base`,
].join('\n');

return [{
  json: {
    ...upstream,
    escalation_id,
    escalation_reason,
    draftPreview,
    draftClean,
    threadLink,
    waMessageText,
  }
}];

const rawText = $json.solutionMd || '';

// ── 1. Fix literal \n strings → actual newlines ───────────────────────────────
let safeText = rawText.replace(/\\n/g, '\n');

// ── 2. Escape < and > INSIDE <code> and <pre> blocks ONLY ────────────────────
// Math operators like D[k] < D[k+1] must be &lt; / &gt; inside code tags
safeText = safeText.replace(/<(code|pre)>([\s\S]*?)<\/\1>/g, (match, tag, inner) => {
  const safeInner = inner
    .replace(/&(?!(lt|gt|amp|quot|apos);)/g, '&amp;') // escape bare & first
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
  return `<${tag}>${safeInner}</${tag}>`;
});

// ── 3. Convert unsupported tags → Telegram equivalents ───────────────────────
safeText = safeText
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<strong>([\s\S]*?)<\/strong>/gi, '<b>$1</b>')
  .replace(/<em>([\s\S]*?)<\/em>/gi, '<i>$1</i>')
  .replace(/<h[1-6][^>]*>([\s\S]*?)<\/h[1-6]>/gi, '<b>$1</b>\n');

// ── 4. Strip all remaining unsupported tags (keep inner text) ─────────────────
safeText = safeText
  .replace(/<sub>([^<]*)<\/sub>/gi, '[$1]')   // E<sub>B</sub> → E[B]
.replace(/<sup>([^<]*)<\/sup>/gi, '^$1')    // x<sup>2</sup> → x^2
.replace(/<\/?(?:span|div|p|ul|ol|li|table|tr|td|th|hr|section|article|figure|img|svg)[^>]*>/gi, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// ── 5. Smart chunking — never cut in the middle of an HTML tag ────────────────
const chunkSize = 3800; // safe buffer below Telegram's 4096 limit
const chunks = [];
let i = 0;

while (i < safeText.length) {
  if (i + chunkSize >= safeText.length) {
    chunks.push({ json: { ...$json, chunk: safeText.slice(i) } });
    break;
  }

  // Walk back from cut point to find a newline or space
  let end = i + chunkSize;
  while (end > i && safeText[end] !== '\n' && safeText[end] !== ' ') {
    end--;
  }
  if (end === i) end = i + chunkSize; // fallback: hard cut

  chunks.push({ json: { ...$json, chunk: safeText.slice(i, end) } });
  i = end;
}

return chunks;

