// ── 0. Extract raw text safely ────────────────────────────────────────────────
const sourceJson = $('When Executed by Another Workflow').first().json;
const inputJson  = $input.first().json;

const raw =
  sourceJson?.solution?.solution    // ← the actual nested string
  ?? sourceJson?.solution           // fallback if it's already a string
  ?? inputJson?.solution?.solution
  ?? inputJson?.solution
  ?? sourceJson?.solutionMd
  ?? inputJson?.solutionMd
  ?? '';


// Force to string regardless of what the upstream node returned
const rawText = typeof raw === 'string'
  ? raw
  : typeof raw === 'object' && raw !== null
    ? JSON.stringify(raw)
    : String(raw ?? '');

// ── 1. Fix literal \n strings → actual newlines ──────────────────────────────
let safeText = rawText.replace(/\\n/g, '\n');

// ── 2. Convert supported HTML variants → Telegram equivalents ────────────────
safeText = safeText
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<strong>([\s\S]*?)<\/strong>/gi, '<b>$1</b>')
  .replace(/<em>([\s\S]*?)<\/em>/gi, '<i>$1</i>')
  .replace(/<h[1-6][^>]*>([\s\S]*?)<\/h[1-6]>/gi, '<b>$1</b>\n')
  .replace(/<sub>([^<]*)<\/sub>/gi, '[$1]')
  .replace(/<sup>([^<]*)<\/sup>/gi, '^$1');

// ── 3. Strip remaining unsupported block/inline tags (keep inner text) ────────
safeText = safeText.replace(
  /<\/?(?:span|div|p|ul|ol|li|table|tr|td|th|hr|section|article|figure|img|svg)[^>]*>/gi,
  ''
);

// ── 4. Collect and protect all VALID Telegram HTML tags ──────────────────────
const placeholders = [];
safeText = safeText.replace(
  /<(\/?(?:b|i|u|s|code|pre)>|a\s[^>]*>|\/a>)/g,
  (match) => {
    const idx = placeholders.length;
    placeholders.push(match);
    return `\x00PLACEHOLDER_${idx}\x00`;
  }
);

// ── 5. Escape ALL remaining bare < and > ─────────────────────────────────────
safeText = safeText
  .replace(/&(?!(lt|gt|amp|quot|apos);)/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// ── 6. Restore valid Telegram HTML tags ──────────────────────────────────────
safeText = safeText.replace(
  /\x00PLACEHOLDER_(\d+)\x00/g,
  (_, idx) => placeholders[Number(idx)]
);

// ── 7. Collapse excess blank lines ────────────────────────────────────────────
safeText = safeText
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// ── 8. Smart chunking ─────────────────────────────────────────────────────────
const chunkSize = 3800;
const chunks = [];
let i = 0;

while (i < safeText.length) {
  if (i + chunkSize >= safeText.length) {
    chunks.push({ json: { ...$json, chunk: safeText.slice(i) } });
    break;
  }
  let end = i + chunkSize;
  while (end > i && safeText[end] !== '\n' && safeText[end] !== ' ') {
    end--;
  }
  if (end === i) end = i + chunkSize;
  chunks.push({ json: { ...$json, chunk: safeText.slice(i, end) } });
  i = end;
}

return chunks;

